<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {request} from './client'
const emit=defineEmits(['close']),dialog=ref(null),token=ref(''),email=ref(''),verified=ref(false),busy=ref(false),error=ref(''),password=ref(''),confirmation=ref(''),done=ref(false),seconds=ref(0)
let poll
async function start(){busy.value=true;error.value='';try{const r=await request('password_reset','start');token.value=r.token;email.value=r.email;seconds.value=r.expires_in;poll=setInterval(check,4000)}catch(e){error.value=e.message}finally{busy.value=false}}
async function check(){if(!token.value||busy.value||done.value||verified.value)return;try{const r=await request('password_reset','status',{token:token.value},'GET');verified.value=r.verified;seconds.value=r.expires_in;if(r.verified)clearInterval(poll)}catch(e){clearInterval(poll);error.value=e.message}}
async function save(){busy.value=true;error.value='';try{await request('password_reset','finish',{token:token.value,password:password.value,confirmation:confirmation.value});password.value='';confirmation.value='';done.value=true;clearInterval(poll)}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>dialog.value.showModal());onBeforeUnmount(()=>{clearInterval(poll);dialog.value?.close()})
</script>
<template><dialog ref="dialog" class="password-dialog" aria-labelledby="password-reset-title" @cancel.prevent="!busy&&emit('close')"><button class="close-reset" aria-label="Close password reset" :disabled="busy" @click="emit('close')">×</button><h2 id="password-reset-title">{{done?'Password updated':'Reset your password'}}</h2><p v-if="error" role="alert">{{error}}</p><section v-if="done"><p>Your new password is saved. A security confirmation is queued for your email and verified mobile. Please sign in again.</p><a class="button primary" href="/campus">Return to sign in</a></section><section v-else-if="!token"><p>First, let’s confirm it’s you. We’ll send a secure link to the email address on your signed-in account.</p><button class="button primary" :disabled="busy" @click="start">{{busy?'Sending…':'Send confirmation email'}}</button></section><section v-else-if="!verified"><p class="reset-notice">Open the confirmation email sent to <strong>{{email}}</strong> and select Confirm password reset.</p><p>Keep this tab open. Your new-password form will appear here after confirmation. The link lasts 10 minutes.</p><button class="button subtle" @click="check">I’ve confirmed — check now</button></section><form v-else @submit.prevent="save"><p class="reset-notice">Email confirmed. Choose your new password.</p><label>New password<input v-model="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></label><label>Confirm new password<input v-model="confirmation" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></label><p>Use 12–128 characters. Both passwords must match.</p><button class="button primary" :disabled="busy||password.length<12||password!==confirmation">{{busy?'Saving…':'Save new password'}}</button></form></dialog></template>
<style scoped>.password-dialog{position:fixed;inset:0;margin:auto;width:min(520px,calc(100vw - 32px));padding:30px;border:1px solid #ddd2ed;border-radius:22px;color:#392b49;background:white;max-height:90vh;overflow:auto}.password-dialog::backdrop{background:#25143988}.password-dialog p{line-height:1.7;margin:18px 0}.password-dialog label{display:grid;gap:8px;margin:16px 0}.password-dialog input{padding:12px;border:1px solid #ccbddd;border-radius:10px}.close-reset{position:absolute;right:15px;top:12px;background:none;border:0;font-size:25px}.reset-notice{padding:16px;background:#f1f8f3;border-radius:14px;color:#28543a}</style>
